// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 sequenceNumber_,
        bytes32 batcherHash_,
        uint256 l1FeeOverhead_,
        uint256 l1FeeScalar_
    ) public {
        vm.prank(DEPOSITOR);
        c.setL1BlockValues(
            number_,
            timestamp_,
            basefee_,
            hash_,
            sequenceNumber_,
            batcherHash_,
            l1FeeOverhead_,
            l1FeeScalar_
        );

        assertTrue(
            c.sequenceNumber() == sequenceNumber_ &&
            c.number() == number_ &&
            c.timestamp() == timestamp_ &&
            c.basefee() == basefee_ &&
            c.hash() == hash_ &&
            c.batcherHash() == batcherHash_ &&
            c.l1FeeOverhead() == l1FeeOverhead_ &&
            c.l1FeeScalar() == l1FeeScalar_,
            "stored L1 block values must equal the supplied arguments"
        );
    }
}
